{
  "name": "am-gitlab-task-loop",
  "version": "1.0.4",
  "description": "OpenCode 插件：定时从 GitLab 获取指派给指定用户的 opened Issue，驱动 AI 完成开发任务，回写评论并关闭 Issue",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "node test/smoke.mjs && node test/scheduler.test.mjs && node test/plugin-contract.test.mjs",
    "clean": "rm -rf dist"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gitlab",
    "issue",
    "automation",
    "task-loop"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.14.19",
    "@opencode-ai/sdk": "1.14.19",
    "@types/node": "^20.19.43",
    "typescript": "^5.5.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
